INSERT INTO gen_template (id, template_name, generator_path, template_desc, template_code, create_time, update_time, del_flag, create_by, update_by) VALUES (33, 'ControllerV2026001', '${backendPath}/src/main/java/${packagePath}/${moduleName}/controller/${ClassName}Controller.java', 'ControllerV2026001', $ymg$package ${package}.${moduleName}.controller;

import cn.hutool.core.util.StrUtil;
