INSERT INTO gen_template (id, template_name, generator_path, template_desc, template_code, create_time, update_time, del_flag, create_by, update_by) VALUES (42, 'api.tsV2026001', '${frontendPath}/src/api/${moduleName}/${functionName}.ts', 'api.tsV2026001', $ymg$import request from "/@/utils/request"

// ========== 基础CRUD接口 ==========

/**
 * 分页查询列表数据
 * @param query - 查询参数对象
 * @returns Promise<分页数据>
 */
export function fetchList(query?: Object) {
  return request({
    url: '/${moduleName}/${functionName}/page',
    method: 'get',
    params: query
  })
}

/**
 * 新增数据
 * @param obj - 要新增的数据对象
 * @returns Promise<boolean> - 操作结果
 */
export function addObj(obj?: Object) {
  return request({
    url: '/${moduleName}/${functionName}',
    method: 'post',
    data: obj
  })
}

/**
 * 获取详情数据
 * @param obj - 查询参数对象（包含ID等）
 * @returns Promise<数据详情>
 */
export function getObj(obj?: Object) {
  return request({
    url: '/${moduleName}/${functionName}/details',
    method: 'get',
    params: obj
  })
}

/**
 * 批量删除数据
 * @param ids - 要删除的ID数组
 * @returns Promise<操作结果>
 */
export function delObjs(ids?: Object) {
  return request({
    url: '/${moduleName}/${functionName}',
    method: 'delete',
    data: ids
  })
}

/**
 * 更新数据
 * @param obj - 要更新的数据对象
 * @returns Promise<操作结果>
 */
export function putObj(obj?: Object) {
  return request({
    url: '/${moduleName}/${functionName}',
    method: 'put',
    data: obj
  })
}

// ========== 树形CRUD接口 ==========

/**
 * 获取树形列表数据
 * @param query - 查询参数对象
 * @returns Promise<树形数据>
 */
export function fetchTreeList(query?: Object) {
  return request({
    url: '/${moduleName}/${functionName}/tree',
    method: 'get',
    params: query
  })
}

/**
 * 获取树节点详情
 * @param obj - 查询参数对象（包含ID等）
 * @returns Promise<树节点详情>
 */
export function getTreeObj(obj?: Object) {
  return request({
    url: '/${moduleName}/${functionName}/tree/details',
    method: 'get',
    params: obj
  })
}

/**
 * 新增树节点
 * @param obj - 要新增的树节点对象
 * @returns Promise<操作结果>
 */
export function addTreeObj(obj?: Object) {
  return request({
    url: '/${moduleName}/${functionName}/tree',
    method: 'post',
    data: obj
  })
}

/**
 * 更新树节点
 * @param obj - 要更新的树节点对象
 * @returns Promise<操作结果>
 */
export function putTreeObj(obj?: Object) {
  return request({
    url: '/${moduleName}/${functionName}/tree',
    method: 'put',
    data: obj
  })
}

/**
 * 删除树节点
 * @param ids - 要删除的树节点ID数组
 * @returns Promise<操作结果>
 */
export function delTreeObjs(ids?: Object) {
  return request({
    url: '/${moduleName}/${functionName}/tree',
    method: 'delete',
    data: ids
  })
}

// ========== 工具函数 ==========

/**
 * 验证字段值唯一性
 * @param rule - 验证规则对象
 * @param value - 要验证的值
 * @param callback - 验证回调函数
 * @param isEdit - 是否为编辑模式
 *
 * @example
 * // 在表单验证规则中使用
 * fieldName: [
 *   {
 *     validator: (rule, value, callback) => {
 *       validateExist(rule, value, callback, form.${pk.attrName} !== '');
 *     },
 *     trigger: 'blur',
 *   },
 * ]
 */
export function validateExist(rule: any, value: any, callback: any, isEdit: boolean) {
  // 编辑模式下跳过验证
  if (isEdit) {
    return callback();
  }

  // 查询是否存在相同值
  getObj({ [rule.field]: value }).then((response) => {
    const result = response.data;
    if (result !== null && result.length > 0) {
      callback(new Error('数据已经存在'));
    } else {
      callback();
    }
  });
}
